add_shortcode( '{{cat_count_shortcode}}', 'perfectpixel_category_count_shortcode' );

function perfectpixel_category_count_shortcode( $atts ) {
	$atts    = shortcode_atts( array( 'id' => 0 ), $atts );
	$term_id = absint( $atts['id'] );
	if ( ! $term_id && function_exists( 'is_product_category' ) && is_product_category() ) {
		$term_id = get_queried_object_id();
	}
	if ( ! $term_id ) {
		return '';
	}
	$ids   = array_merge( array( $term_id ), get_term_children( $term_id, 'product_cat' ) );
	$count = count(
		get_posts(
			array(
				'post_type'      => 'product',
				'post_status'    => 'publish',
				'fields'         => 'ids',
				'posts_per_page' => -1,
				'no_found_rows'  => true,
				'tax_query'      => array( array( 'taxonomy' => 'product_cat', 'terms' => $ids ) ),
			)
		)
	);
	return '<span class="perfectpixel-cat-count">' . esc_html( number_format_i18n( $count ) ) . '</span>';
}
